import {
  component$,
  useStyles$,
  useSignal,
  useContextProvider,
} from "@qwik.dev/core";
import { AuthContext, type AuthState } from "../../utils/auth-context";
import { ConvexProvider } from "../../utils/convex-context";
import type { Meta, StoryObj } from "storybook-framework-qwik";
import type { SentenceLabProps } from "./catalog";
import { SentenceBench } from "./sentence-bench";
import {
  OFFLINE_BENCH_FIXTURE,
  SETTLED_BENCH_FIXTURE,
  STALE_BENCH_FIXTURE,
} from "./sentence-bench.fixtures";
const Preview = component$<{ fixture: SentenceLabProps }>(({ fixture }) => {
  useContextProvider(
    AuthContext,
    useSignal<AuthState>({ user: null, loading: false }),
  );
  useStyles$(
    `.sentence-story { min-height:100dvh; padding:3rem 1rem; background:var(--color-paper-2); color:var(--color-ink); } .sentence-story aside { max-width:30rem; margin:auto; background:var(--color-paper); border:1px solid var(--color-paper-3); border-radius:2px; padding:1rem; } .sentence-story h1 { font:600 1.25rem var(--font-display); margin-bottom:1rem; }`,
  );
  return (
    <ConvexProvider>
      <main class="sentence-story">
        <aside aria-label="Sentence bench preview">
          <h1>Sentence bench</h1>
          <SentenceBench props={fixture} filling={false} toolId="story" />
        </aside>
      </main>
    </ConvexProvider>
  );
});
const meta = {
  title: "Writing instruments/Sentence bench",
  component: Preview,
  parameters: { layout: "fullscreen" },
  args: { fixture: OFFLINE_BENCH_FIXTURE },
} satisfies Meta<{ fixture: SentenceLabProps }>;
export default meta;
type Story = StoryObj<{ fixture: SentenceLabProps }>;
export const Offline: Story = {};
export const SettledHistory: Story = {
  args: { fixture: SETTLED_BENCH_FIXTURE },
};
export const Stale: Story = { args: { fixture: STALE_BENCH_FIXTURE } };
import type { SentenceLabProps } from "./catalog";
import {
  localSentenceCandidates,
  sentenceContext,
  sentencePlacementChoices,
} from "../../utils/sentence-bench";
export const BENCH_SENTENCE =
  "We made a decision to leave in order to find a very quiet room.";
export const BENCH_PARAGRAPH = `The old map remained. ${BENCH_SENTENCE} We followed the river.`;
const from = BENCH_PARAGRAPH.indexOf(BENCH_SENTENCE);
export const OFFLINE_BENCH_FIXTURE: SentenceLabProps = {
  sentence: BENCH_SENTENCE,
  sentenceId: "fixture-map-room",
  attempts: [],
  variants: [],
  candidates: localSentenceCandidates(BENCH_SENTENCE),
  context: sentenceContext(BENCH_PARAGRAPH, from, from + BENCH_SENTENCE.length),
  placements: sentencePlacementChoices(
    BENCH_PARAGRAPH,
    from,
    from + BENCH_SENTENCE.length,
  ),
};
export const STALE_BENCH_FIXTURE: SentenceLabProps = {
  ...OFFLINE_BENCH_FIXTURE,
  stale: true,
};
export const SETTLED_BENCH_FIXTURE: SentenceLabProps = {
  ...OFFLINE_BENCH_FIXTURE,
  attempts: ["We chose a quieter room before setting out."],
  candidates: localSentenceCandidates(BENCH_SENTENCE, [
    {
      text: "We chose a quieter room before setting out.",
      at: 1770000000000,
      source: "yours",
    },
  ]),
};
.sentence-bench {
  color: var(--color-ink);
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}
.in-flow-rails:has(.sentence-bench) {
  z-index: 4;
}
/* The rail scrolls as a whole, but the working wording and its use control
 * come first, so the decision is in view the moment the bench opens. */
.in-flow-rail:has(.sentence-bench) {
  max-height: 70dvh;
  overflow: auto;
  overscroll-behavior: contain;
}
/* In the narrow dock the bench is a bounded sheet, so its working copy and
 * use control stay reachable. */
.in-flow-dock:has(.sentence-bench) {
  max-height: 60dvh;
}
.sentence-bench .in-flow-label {
  display: block;
  margin-bottom: 0.3rem;
}
.sentence-bench-textarea {
  font: 1rem/1.55 var(--font-serif);
  min-height: 4.75rem;
}
.sentence-bench-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5rem;
  margin-top: 0.5rem;
}
.sentence-bench-actions .btn-press {
  min-height: 2.25rem;
}
.sentence-bench-tabs {
  display: flex;
  gap: 0;
  border: 1px solid var(--color-paper-3);
  border-radius: 2px;
  padding: 2px;
  background: var(--color-paper-soft);
}
.sentence-bench-tabs button,
.sentence-bench-word-line button,
.sentence-bench-link,
.sentence-bench-side {
  font: inherit;
  color: var(--color-ink);
  border: 0;
  background: transparent;
  cursor: pointer;
}
.sentence-bench-tabs button {
  flex: 1 1 0;
  min-height: 2rem;
  padding: 0.3rem 0.4rem;
  font: 500 0.78rem var(--font-sans);
  border-radius: 1px;
}
.sentence-bench-tabs button:hover {
  background: var(--color-paper-2);
}
.sentence-bench-tabs .is-on,
.sentence-bench-tabs .is-on:hover {
  background: var(--color-ink);
  color: var(--color-paper);
}
.sentence-bench button:focus-visible,
.sentence-bench summary:focus-visible {
  outline: 2px solid var(--color-cobalt);
  outline-offset: 2px;
}
.sentence-bench-candidates > li {
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: stretch;
  gap: 0.25rem;
}
.sentence-bench .in-flow-choice {
  font: 0.9375rem/1.5 var(--font-serif);
  padding: 0.45rem 0.55rem;
}
.sentence-bench-side {
  font: 0.72rem var(--font-sans);
  padding: 0 0.45rem;
  border: 1px solid transparent;
  border-radius: 2px;
  text-decoration: underline;
  text-underline-offset: 2px;
}
.sentence-bench-side:hover,
.sentence-bench-side[aria-pressed="true"] {
  border-color: var(--color-paper-3);
  background: var(--color-paper-soft);
}
.sentence-bench-slot {
  border-bottom: 1px solid var(--color-paper-3);
  padding-bottom: 0.6rem;
}
.sentence-bench-meta {
  display: block;
  margin-top: 0.25rem;
  font: 0.6875rem/1.4 var(--font-sans);
  color: var(--color-ink-light);
}
.sentence-bench-chip {
  display: inline-block;
  border: 1px solid var(--color-paper-3);
  border-radius: 1rem;
  padding: 0 0.35rem;
