}
.sentence-bench-word-line .is-on,
.sentence-bench-word-line .is-on:hover {
  background: var(--color-highlight-mint);
}
.sentence-bench-link {
  font: 0.75rem var(--font-sans);
  text-decoration: underline;
  text-underline-offset: 2px;
  padding: 0.3rem 0.2rem;
}
.sentence-bench-pane {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}
.sentence-bench-preview,
.sentence-bench-comparison p {
  font: 0.875rem/1.6 var(--font-serif);
  margin: 0.4rem 0 0;
}
.sentence-bench-comparison {
  border: 1px solid var(--color-paper-3);
  border-radius: 2px;
  padding: 0.5rem 0.6rem;
  background: var(--color-paper-soft);
}
.sentence-bench-notice {
  font: 0.8125rem/1.5 var(--font-sans);
  border-left: 2px solid var(--color-ink);
  padding-left: 0.5rem;
  margin: 0.4rem 0 0;
}
.sentence-bench-about,
.sentence-bench-room {
  font: 0.75rem/1.5 var(--font-sans);
}
.sentence-bench-about > summary,
.sentence-bench-room > summary {
  cursor: pointer;
  padding: 0.3rem 0;
  color: var(--color-ink-light);
}
.sentence-bench-about ul {
  margin: 0.2rem 0 0;
  padding-left: 1rem;
  color: var(--color-ink-light);
}
.sentence-bench-room {
  border-top: 1px solid var(--color-paper-3);
  padding-top: 0.35rem;
}
.sentence-bench-room > summary {
  color: var(--color-ink);
}
@media (max-width: 480px) {
  .sentence-bench-tabs button {
    min-height: 2.5rem;
  }
  .sentence-bench-side {
    min-width: 2.75rem;
  }
}

