192	/** Reject new Harper problems; existing problems are not silently blessed. */
193	export async function checkSentenceCandidates(
194	  original: string,
195	  candidates: SentenceCandidate[],
196	  lint: SentenceLint,
197	): Promise<SentenceCandidate[]> {
198	  const baseline = await lint(original);
199	  const signature = (i: GrammarIssue) =>
200	    `${i.kind}:${i.problem.toLocaleLowerCase()}:${i.message}`;
201	  const allowed = new Map<string, number>();
202	  baseline.forEach((i) =>
203	    allowed.set(signature(i), (allowed.get(signature(i)) ?? 0) + 1),
204	  );
205	  const result: SentenceCandidate[] = [];
206	  // Harper's worker mutates dictionary state: use one sequential queue.
207	  for (const candidate of candidates) {
208	    if (!completeSentence(candidate.text)) continue;
209	    const issues = await lint(candidate.text);
210	    const counts = new Map<string, number>();
211	    issues.forEach((i) =>
212	      counts.set(signature(i), (counts.get(signature(i)) ?? 0) + 1),
213	    );
214	    if ([...counts].every(([key, count]) => count <= (allowed.get(key) ?? 0)))
215	      result.push({ ...candidate, grammar: "checked" });
216	  }
217	  return result;
218	}
