220	/** Word-level LCS retains punctuation and whitespace for a full reversible diff. */
221	export function sentenceWordDiff(before: string, after: string): WordDiff[] {
222	  const tokens = (s: string) =>
223	    s.match(/\s+|[\p{L}\p{N}]+(?:['’][\p{L}]+)*|[^\s\p{L}\p{N}]/gu) ?? [];
224	  const a = tokens(before),
225	    b = tokens(after);
226	  // Sentence limit bounds the matrix; do not allocate it for arbitrary documents.
227	  if (a.length * b.length > 160000)
228	    return [
229	      { kind: "removed", text: before },
230	      { kind: "added", text: after },
231	    ];
232	  const dp = Array.from(
233	    { length: a.length + 1 },
234	    () => new Uint16Array(b.length + 1),
235	  );
236	  for (let i = a.length - 1; i >= 0; i--)
237	    for (let j = b.length - 1; j >= 0; j--)
238	      dp[i][j] =
239	        a[i] === b[j]
240	          ? 1 + dp[i + 1][j + 1]
241	          : Math.max(dp[i + 1][j], dp[i][j + 1]);
242	  const out: WordDiff[] = [];
243	  const push = (kind: WordDiff["kind"], text: string) => {
244	    const last = out.at(-1);
245	    if (last?.kind === kind) last.text += text;
246	    else out.push({ kind, text });
247	  };
248	  let i = 0,
249	    j = 0;
250	  while (i < a.length || j < b.length) {
251	    if (i < a.length && j < b.length && a[i] === b[j]) {
252	      push("same", a[i++]);
253	      j++;
254	    } else if (j < b.length && (i === a.length || dp[i][j + 1] > dp[i + 1][j]))
255	      push("added", b[j++]);
256	    else push("removed", a[i++]);
257	  }
258	  return out;
259	}
