417	export function wordAlternatives(
418	  sentence: string,
419	  from: number,
420	  to: number,
421	): WordAlternative[] {
422	  const word = sentence.slice(from, to);
423	  if (!sentenceWords(sentence).some((w) => w.from === from && w.to === to))
424	    return [];
425	  return (WORDS[word.toLocaleLowerCase()] ?? []).map(
426	    ([replacement, nuance]) => {
427	      const cased =
428	        word === word.toUpperCase()
429	          ? replacement.toUpperCase()
430	          : /^[A-Z]/.test(word)
431	            ? capitalise(replacement)
432	            : replacement;
433	      return {
434	        word,
435	        replacement: cased,
436	        from,
437	        to,
438	        sentence: sentence.slice(0, from) + cased + sentence.slice(to),
439	        nuance,
440	        source: "thesaurus",
441	      };
442	    },
443	  );
444	}
